# ---------------------------------------------------------------- trims and fittings
CARDS.append(dict(id="CA13", title="Trim strips, body creases and shut lines that follow the body", needs=["CA04"],
 files=["tools/art/parts/trim.py", "tests/run_ca13.sh"],
 goal="Chrome sill and waist strips, pressed body creases, and the door, bonnet and boot shut lines: thin ribbons that hug the curved flank. Registers `strip`, `crease`, `shutline`.",
 read=[BL, FW, SPEC, COORD, "tools/art/surface.py (`half_width`)"],
 steps=[
  "`tools/art/parts/trim.py`: helper `ribbon(name, pts, thick, height, mat)` where `pts` is a list of (x, y, lat) car-coordinate points; it builds a bmesh strip: for each point a short vertical quad of `height` units centred on y, pushed outward by `thick` along lat (sign of lat); consecutive points joined (so it is a thin band hugging the surface). Helper `flank_points(surf, x0, x1, y, s, step=2.0)` -> points `(x, y, s*(surf.half_width(x, y) + 0.05))` every `step` units. `@register('strip')` = chrome (or black / paint2) ribbon, `thick 0.35`, `height h`, named `strip_<i>_<s>`; `role` window uses `window_frame` colour. `@register('crease')` = `thick depth+0.05`, `height 0.3`, material `paint2` lightened (or the paint itself) named `crease_<i>_<s>`.",
  "`@register('shutline')`: for a `path` [[x,y],...] on the flank: resample each segment every 1.5 units, `lat = s*(half_width(x,y)+0.03)`, ribbon `thick 0.1`, `height 0.28`, material `dark`, name `shutline_<i>_<s>`. If `across_x` is set, add a second ribbon across the top at that x: points from lat -L to +L every 2 units, `y = surf.top(across_x) - 0.05` and L = `surf.half_width(across_x, top-1)*0.9` (a bonnet or boot lid edge), named `shutline_<i>_top`.",
  blender_test("run_ca13.sh", "`tests/fixtures/details_trim.json` (create it: dossier_ok, 1 strip `sill` x -34..34 y 6, 1 strip `waist` x -30..22 y 26.5, 1 crease x -40..40 y 20, 2 shutlines (a door path [[8,26.5],[8,7]] and a bonnet path [[24,26.5],[24,8]] with across_x 24))", "at least 4 `REPORT strip_` lines, 2 `REPORT crease_` lines and at least 5 lines starting `REPORT shutline_` (door 2 sides, bonnet 2 sides, bonnet top 1)"),
 ],
 accept=["`sh tests/run_ca13.sh` prints `CA13 OK`.", "`sh tests/run_ca04.sh` still prints `CA04 OK`."]))

