PER_CAR_RULES = ("Rules for the details file: schema `docs/CAR_DETAILS_SPEC.md` (CA01). Read the dossier's `front`, `rear`, `side_features`, `special`, `side_profile`, `greenhouse`, `wheels`, `typical_paint` and TRANSLATE every feature there into a part with exact numbers from the dossier (never invent a number that the dossier gives). "
                 "Mirror pairs use `side: both`. `belt_y` = the height of the lowest point of the greenhouse polygon on the doors. `windows` = split the greenhouse into side panes at the B pillar (one pane per door window; one rear quarter pane if any; the windscreen and rear glass stay in the side-view polygon as their slanted outline) with the pillar bands as `pillars` entries (A pillar: from the windscreen base up to the roof along the screen edge, `lat_from` 0.82). `caricature`: `eyes` 1.15, `mouth` 1.1, `wheels` 1.05, `bumper` 1.1 unless a note below says otherwise (the RSAMH-style comic exaggeration). Paint: the main colour always comes from the dossier (`typical_paint[0]`); write `paint.colour2` and `paint.zones` (`use` paint2 or vinyl) only for a two-tone car, a vinyl roof or stripes that the dossier lists, and `paint.finish` metallic only when the dossier says so. The DEFAULT picture of every car is the SIDE view (Lee, 14 Oct 2026): flank, windows, pillars, arches and wheels must be right first; front and rear parts feed the head-on face portrait and the extra three-quarter view.")


def car_card(cid, car, dossier_card, title_name, recog, extra_steps=None, needs_extra=()):
    steps = [
        "Open `docs/cars/%s.json`. Write `docs/cars/details/%s.json` (create the folder): version 2, id, `belt_y`, `window_frame`, `caricature`, `wheel` (style and `hub`/`whitewall` from the dossier wheel style and the recognisers below), `roof`, `windows` and `pillars` (see rules). Then the FRONT parts: the headlamps, small lamps, grille, bumper, plate, badges. " % (car, car),
        "REAR parts: tail lamps, bumper, plate, exhaust, boot or hatch handle, badges, reversing lamp, fuel cap. SIDE parts (the side view is the DEFAULT picture of every car, so do these most carefully): strips, creases, shut lines for EVERY door, bonnet and boot lid (a path per line), door handles, mirrors (only if the era had them: say in `note`), vents, fins or running boards if any. At least 24 parts in total.",
        "Recognisers for this car (the things a person uses to know it: each must appear as a part, or as `wheel` / `paint` / `roof` setting): " + recog,
    ]
    if extra_steps:
        steps.extend(extra_steps)
    steps.append("Validate and fix until clean: `python3 tools/art/details.py docs/cars/details/%s.json --dossier docs/cars/%s.json --strict`. " % (car, car) + PER_CAR_RULES)
    return dict(id=cid, title="Details for %s (%s)" % (car, title_name), needs=["CA01", dossier_card],
                files=["docs/cars/details/%s.json" % car],
                goal="Fill the structured details file for the game car `%s` so the Blender builder can add its lamps, grille, bumpers, trim, handles and badges. This is data only." % car,
                read=["docs/CAR_DETAILS_SPEC.md (CA01: every kind, field and default)", "docs/cars/%s.json (the dossier: coordinates and the free-text features you must translate)" % car,
                      "tests/fixtures/details_ok.json (a small valid example)", COORD],
                steps=steps,
                accept=["`python3 tools/art/details.py docs/cars/details/%s.json --dossier docs/cars/%s.json --strict` prints `DETAILS OK %s parts=` with parts >= 24 and kinds >= 8." % (car, car, car)],
                oos=["Everything not listed under files (do not edit the dossier; if a dossier number looks wrong write `note` and keep it)."])


